struct Ref:H8SEmulator{void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t at;uint32_t addr;uint8_t value;bool write;};
static bool mapped(uint32_t a){return (a>=0x600000&&a<0x600010)||(a>=0xc598&&a<0xc59a)||(a>=0xfffe50&&a<0xfffe80)||a==0xbb1c||a==0xbab0;}
struct RBus:H8SDevice{Ref&c;unsigned group=0;std::array<Event,16>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=a==0x600004?uint8_t(group==1?16:7):c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;if(a==0x600000&&v==8)group=1;if(a==0x60000e)group=2;}};
struct NBus:kstation::ControllerResourceBus{unsigned group=0;bool enabled=false;std::array<Event,16>e{};unsigned n=0;bool mapped(uint32_t a)const override{return ::mapped(a);}uint8_t read(uint32_t a)override{auto v=a==0x600004?uint8_t(group==1?16:7):state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;if(a==0x600000&&v==8)group=1;if(a==0x60000e)group=2;}};
int main(int argc,char**argv){if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0x600000,16);c->memmap(&x,0xc598,2);c->memmap(&x,0xfffe50,0x30);c->memmap(&x,0xbb1c,1);c->memmap(&x,0xbab0,1);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerDspTransferRuntime dsp;kstation::ControllerForegroundClockRuntime vol;if(!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!dsp.bindVerifiedFirmware(*d,rom.data(),rom.size())||!vol.bindVerifiedFirmware(*d,rom.data(),rom.size()))return 2;y.enabled=true;uint64_t graphs=0,phases=0,events=0,shorts=0,writes=0;for(unsigned value=0;value<256;++value)for(unsigned mode=0;mode<8;++mode){irq.reset();dsp.reset();vol.reset();unsigned flags=value;irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);x.group=y.group=0;for(unsigned i=0;i<16;++i)c->memory[0x600000+i]=d->memory[0x600000+i]=0;c->memory[0xc598]=d->memory[0xc598]=0xff;c->memory[0xc599]=d->memory[0xc599]=0xff;auto put=[&](unsigned a,uint8_t v){c->memory[a]=d->memory[a]=v;};auto word=[&](unsigned a,uint16_t v){put(a,v>>8);put(a+1,v);};auto wide=[&](unsigned a,uint32_t v){word(a,v>>16);word(a+2,v);};put(0xfffe70,uint8_t(mode&1));put(0xbb1c,uint8_t((mode>>1)&3));put(0xfffe6f,3);put(0xbab0,uint8_t(value));wide(0xfffe56,0x01020304+value);wide(0xfffe66,0x12345678+value);word(0xfffe78,uint16_t(0x3456+value));word(0xfffe7c,mode&2?0x80:0x800);wide(0xfffe6a,0x456789ab+value);wide(0xfffe62,0x12345678+value);c->pc=c->makepc(0x1838);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg32(1)=int32_t(0x9a6c1234);c->reg8(6)=int8_t(value);c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;if(!vol.start())return 3;for(unsigned k=0;vol.active();++k){if(k>10000)return 4;auto at=uint32_t(c->getPC());x.n=y.n=0;auto cost=vol.nextClocks(*d,irq,dsp);if(!cost)return 5;for(unsigned b=0;b<cost;++b){auto before=d->cycles;auto r=vol.advanceBefore(*d,irq,dsp,b);if(r.clocks||d->cycles!=before||y.n)return 6;++shorts;}c->step();auto r=vol.advanceBefore(*d,irq,dsp,cost);if(!r.clocks||c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x v=%u clocks=%llu/%llu io=%u/%u\n",at,value,c->cycles,d->cycles,x.n,y.n);return 7;}for(unsigned i=0;i<x.n;++i){auto a=x.e[i],b=y.e[i];if(a.at!=b.at||a.addr!=b.addr||a.value!=b.value||a.write!=b.write){std::fprintf(stderr,"event pc=%x mode=%u value=%u addr=%x/%x val=%x/%x time=%llu/%llu\n",at,mode,value,a.addr,b.addr,a.value,b.value,a.at,b.at);std::fprintf(stderr,"ER1=%x ratio=%02x%02x%02x%02x/%02x%02x%02x%02x\n",uint32_t(c->reg32(1)),c->memory[0xfffe6a],c->memory[0xfffe6b],c->memory[0xfffe6c],c->memory[0xfffe6d],d->memory[0xfffe6a],d->memory[0xfffe6b],d->memory[0xfffe6c],d->memory[0xfffe6d]);return 8;}if(b.write&&b.addr==0x60000e)++writes;}events+=x.n;++phases;}if(c->getPC()!=0x7000)return 9;++graphs;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu,\"dsp_writes\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts,(unsigned long long)writes);}
